    41→    const [balanceMap, allStockIns] = await Promise.all([
    42→      computeStockBalances(storeId),
    43→      getAll<StockInType>(COLLECTIONS.STOCK_IN),
    44→    ]);
    45→
    46→    const activeStockIns = allStockIns
    47→      .filter(si => si.status !== "voided")
    48→      .sort((a, b) => {
    49→        const ta = a.createdAt ? new Date(a.createdAt as any).getTime() : 0;
    50→        const tb = b.createdAt ? new Date(b.createdAt as any).getTime() : 0;
    51→        return tb - ta;
    52→      });
    53→
    54→    const priceMap: Record<string, { unitPrice: number; cartonPrice: number }> = {};
    55→    for (const si of activeStockIns) {
    56→      for (const item of si.items) {
    57→        if (!priceMap[item.productId] && (item.unitPrice > 0 || item.cartonPrice > 0)) {
    58→          priceMap[item.productId] = {
    59→            unitPrice: item.unitPrice,
    60→            cartonPrice: item.cartonPrice,
    61→          };
    62→        }
    63→      }
    64→    }
    65→
    66→    const rows: BalanceRow[] = Object.values(balanceMap).map(b => ({
    67→      ...b,
    68→      unitPrice: priceMap[b.productId]?.unitPrice ?? 0,
    69→      cartonPrice: priceMap[b.productId]?.cartonPrice ?? 0,
    70→    }));
    71→
    72→    setBalance(rows);
