    11→/** Read a Blob as a base64 data URL */
    12→function blobToDataUrl(blob: Blob): Promise<string> {
    13→  return new Promise((resolve, reject) => {
    14→    const reader = new FileReader();
    15→    reader.onload = () => resolve(reader.result as string);
    16→    reader.onerror = reject;
    17→    reader.readAsDataURL(blob);
    18→  });
