    22→function getImageDimensions(dataUrl: string): Promise<{ w: number; h: number }> {
    23→  return new Promise((resolve) => {
    24→    const img = new Image();
    25→    img.onload = () => resolve({ w: img.naturalWidth, h: img.naturalHeight });
    26→    img.onerror = () => resolve({ w: 0, h: 0 });
