    31→/**
    32→ * Temporarily resolves CSS custom-property (variable) colours to concrete
    33→ * computed values so dom-to-image inlines them correctly.
    34→ * Without this, colours like `hsl(var(--muted-foreground))` render as
    35→ * transparent / black in the captured image.
    36→ */
    37→async function withResolvedStyles<T>(
    38→  root: HTMLElement,
    39→  fn: () => Promise<T>
    40→): Promise<T> {
    41→  const saved: { node: HTMLElement; prev: string }[] = [];
    42→
    43→  const nodes = [root, ...Array.from(root.querySelectorAll("*"))];
    44→  for (const el of nodes) {
    45→    if (!(el instanceof HTMLElement)) continue;
    46→    saved.push({ node: el, prev: el.getAttribute("style") ?? "" });
    47→    const cs = window.getComputedStyle(el);
    48→    const props = [
    49→      "color",
    50→      "background-color",
    51→      "border-top-color",
    52→      "border-right-color",
    53→      "border-bottom-color",
    54→      "border-left-color",
    55→      "font-family",
    56→      "font-size",
    57→      "font-weight",
    58→      "line-height",
    59→    ];
    60→    for (const p of props) {
    61→      const v = cs.getPropertyValue(p);
    62→      if (v) el.style.setProperty(p, v, "important");
    63→    }
    64→  }
    65→
    66→  try {
    67→    return await fn();
    68→  } finally {
    69→    for (const { node, prev } of saved) {
    70→      if (prev) node.setAttribute("style", prev);
    71→      else node.removeAttribute("style");
    72→    }
    73→  }
    74→}
