    88→    const blob: Blob = await withResolvedStyles(element, () =>
    89→      domtoimage.toBlob(element, DOM_TO_IMAGE_OPTS)
    90→    );
    91→    if (!blob) return "failed";
    92→
    93→    const file = new File([blob], filename, { type: "image/png" });
    94→
    95→    if (
    96→      typeof navigator !== "undefined" &&
    97→      navigator.canShare &&
    98→      navigator.canShare({ files: [file] })
    99→    ) {
